#include "re3_codec.h"
#include <stdio.h>
int main(int argc,char **argv){re3c_model m;re3c_u32 i;int r;if(argc!=2){fprintf(stderr,"usage: %s file.EMD\n",argv[0]);return 2;}re3c_model_init(&m);r=re3c_open_file(&m,argv[1]);if(r!=RE3C_OK){fprintf(stderr,"open: %s\n",re3c_result_string(r));return 1;}if(!m.binary01_morph.present){puts("Binary01 morph: not present");re3c_model_close(&m);return 0;}printf("Binary01 mask=%08X tracks=%u end=%u rest=%u validated=%u\n",(unsigned)m.binary01_morph.part_mask,(unsigned)m.binary01_morph.track_count,(unsigned)m.binary01_morph.records_end,(unsigned)m.binary01_morph.rest_pos_size,(unsigned)m.binary01_morph.validated);for(i=0;i<m.binary01_morph.track_count;i++){const re3c_morph_track*t=&m.binary01_morph.tracks[i];printf("track=%u part=%u verts=%u frames=%u stride=%u data=%u reserved_nonzero=%u\n",(unsigned)i,(unsigned)t->part_index,(unsigned)t->vertex_count,(unsigned)t->frame_count,(unsigned)t->frame_stride,(unsigned)t->data_offset,(unsigned)t->reserved_nonzero_count);}re3c_model_close(&m);return 0;}
